 * @param {{ number?: string, customerName: string, lines: Array, status: string, dueDate?: string, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or DRAFT
  const invoiceNumber = invoice.number ?? 'DRAFT';
  lines.push(invoiceNumber);

  // Second line: customer name
  lines.push(invoice.customerName);

  // One line per invoice line
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let lineText = `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;

    // Add discount if present
    if (line.discountPercent && line.discountPercent > 0) {
      const discount = lineDiscount(line);
      lineText += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }

    lines.push(lineText);
  }

  // Subtotal, discount, VAT, voucher, total
  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }
  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount if there are payments
  const paid = totals.total - balanceDue(invoice);
  if (paid > 0) {
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

