import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for unsent invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText shows invoice number when issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  const issuedInvoice = issueResult.value;

  const text = renderInvoiceText(issuedInvoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0001');
});

test('renderInvoiceText includes customer name', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText formats line items with qty, name, price and total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '5x Development (hour) @ €95.00 = €475.00');
});

test('renderInvoiceText shows total in last line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(text, /Total: €2,026.75/);
});

test('renderInvoiceText handles multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines.length, 7);
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '2x Development (hour) @ €95.00 = €190.00');
  assert.equal(lines[3], '3x Copywriting (hour) @ €60.00 = €180.00');
  assert.equal(lines[4], '1x Logo package @ €1,200.00 = €1,200.00');
  assert.match(lines[5], /^VAT:/);
  assert.match(lines[6], /^Total:/);
});

test('renderInvoiceText uses formatEuros for all amounts', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[2], /€/);
  assert.match(lines[3], /€/);
  assert.equal(lines[2], '10x Icon set (24 icons) @ €9.80 = €98.00');
  assert.equal(lines[3], '100x Sticker sheet @ €0.50 = €50.00');
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText works with VAT-exempt products', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[2], /1x Brand workshop \(day, VAT exempt\)/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText handles products with various price points', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /1x Printed flyer A4/);
  assert.match(text, /1x Brand guidelines document/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText renders multi-line output correctly', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 4 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.equal(typeof text, 'string');
  assert.match(text, /DRAFT\n/);
  assert.match(text, /Blue Fern Bakery\n/);
  assert.match(text, /Total: /);
});

test('renderInvoiceText produces the same output for identical invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const text1 = renderInvoiceText(invoice);
  const text2 = renderInvoiceText(invoice);

  assert.equal(text1, text2);
});

test('renderInvoiceText shows discount on line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[2], /10% off/);
  assert.match(lines[2], /-€95.00/);
});

test('renderInvoiceText shows subtotal and discount line when discounts apply', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 5 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(text, /Subtotal:/);
  assert.match(text, /Discount:/);
  assert.match(lines[lines.length - 1], /^Total:/);
});

test('renderInvoiceText does not show discount line when no discounts', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Subtotal:'));
  assert.ok(!text.includes('Discount:'));
});

test('renderInvoiceText handles decimal discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 12.5 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /12.5% off/);
});

test('renderInvoiceText with 100% discount shows zero total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Total: €0.00/);
});

test('renderInvoiceText shows VAT line for products with VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /VAT:/);
  assert.match(text, /€/);
});

test('renderInvoiceText does not show VAT line when no VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('VAT:'));
});

test('renderInvoiceText shows VAT just before total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  const secondLastLine = lines[lines.length - 2];

  assert.match(lastLine, /^Total:/);
  assert.match(secondLastLine, /^VAT:/);
});

test('renderInvoiceText with discount and VAT shows subtotal, discount, VAT, and total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Discount:/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
