  assert.match(lastLine, /^Total:/);
  assert.match(secondLastLine, /^VAT:/);
});

test('renderInvoiceText with discount and VAT shows subtotal, discount, VAT, and total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Discount:/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText shows voucher when applied', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;
  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 10000 }).value;

  const text = renderInvoiceText(withVoucher);
  assert.match(text, /Voucher:/);
  assert.match(text, /-€100.00/);
});

test('renderInvoiceText does not show voucher when none applied', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Voucher:'));
});

test('renderInvoiceText shows due date when present', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    terms: 'NET14',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []).value;

  const text = renderInvoiceText(issued);
  assert.match(text, /Due: 2026-10-21/);
});

test('renderInvoiceText does not show due date when not issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: 50000, date: '2026-10-20' }).value;

  const text = renderInvoiceText(paid);
  assert.match(text, /Paid: €500.00/);
});

test('renderInvoiceText does not show paid amount when no payments', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []).value;

  const text = renderInvoiceText(issued);
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText with all features', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    terms: 'NET14',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;
  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 10000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-10-20' }).value;

  const text = renderInvoiceText(paid);
  assert.match(text, /Due: 2026-10-21/);
  assert.match(text, /Voucher:/);
  assert.match(text, /Paid:/);
  const lines = text.split('\n');
  assert.match(lines[lines.length - 1], /Paid:/);
});

test('renderInvoiceText line discount shown for qualifying lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines[3].includes('10% off'));
  assert.ok(!lines[2].includes('off'));
});

