test('renderInvoiceText with all features', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    terms: 'NET14',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;
  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 10000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-10-20' }).value;

  const text = renderInvoiceText(paid);
  assert.match(text, /Due: 2026-10-21/);
  assert.match(text, /Voucher:/);
  assert.match(text, /Paid:/);
  const lines = text.split('\n');
  assert.match(lines[lines.length - 1], /Paid:/);
});

test('renderInvoiceText line discount shown for qualifying lines', () => {
