    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines[3].includes('10% off'));
  assert.ok(!lines[2].includes('off'));
});

